 "content": "def transform(grid):
    """Replace background-colored single-cell gaps between equal markers with 2."""
    out = [row[:] for row in grid]
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] == row[c + 1] and row[c - 1] != background:
                out[r][c] = 2
    return out
